def has_horizontal_symmetry(grid):
    """Check if grid has horizontal axis symmetry"""
    rows = len(grid)
    for r1, r2 in [(i, rows-1-i) for i in range(rows // 2)] + ([(rows//2, rows//2)] if rows % 2 else []):
        if grid[r1] != grid[r2]:
            return False
    return True

def has_vertical_symmetry(grid):
    """Check if grid has vertical axis symmetry"""
    cols = len(grid[0])
    for c1, c2 in [(i, cols-1-i) for i in range(cols // 2)] + ([(cols//2)] if cols % 2 else []):
        for r in range(rows):
            if grid[r][c1] != grid[r][c2]:
                return False
    return True

def check_point_symmetry(grid):
